changeSet.sql:
ALTER TABLE work_order_category ADD COLUMN IF NOT EXISTS tolerance_minutes INT;
ALTER TABLE work_order_category ADD COLUMN IF NOT EXISTS default_estimated_duration_minutes INT;
ALTER TABLE work_order_category ADD COLUMN IF NOT EXISTS default_checklist_id BIGINT;
ALTER TABLE work_order_category ADD COLUMN IF NOT EXISTS require_signature BOOLEAN NOT NULL DEFAULT FALSE;
