ALTER TABLE work_order_category ADD COLUMN IF NOT EXISTS require_checklist_completion BOOLEAN NOT NULL DEFAULT FALSE;

ALTER TABLE work_order_category DROP CONSTRAINT IF EXISTS fk_work_order_category_default_checklist;
ALTER TABLE work_order_category
    ADD CONSTRAINT fk_work_order_category_default_checklist
    FOREIGN KEY (default_checklist_id) REFERENCES checklist(id) ON DELETE SET NULL;

-- Campos para o tecnico preencher quando a categoria exigir (assinante e km rodado).
ALTER TABLE work_order ADD COLUMN IF NOT EXISTS signer_name VARCHAR(255);
ALTER TABLE work_order ADD COLUMN IF NOT EXISTS signer_document VARCHAR(32);
ALTER TABLE work_order ADD COLUMN IF NOT EXISTS mileage_traveled DOUBLE PRECISION;

